.VerifyChanges <- function(path,
                           private) {
  # generated by make, local only, or secret: never compared
  skip <- paste(
    c(
      "^\\.git/",
      "^\\.verify/",
      "^\\.sif/",
      "^\\.setup/data-external/",
      "^\\.setup/data-cache/",
      "^\\.library/",
      "^\\.claude/",
      "^\\.Rproj\\.user/",
      "^\\.quarto/",
      "^detritus",
      "^docs/",
      "^pkgdown/",
      "^quarto/",
      "^\\.setup/build/",
      "^\\.setup/quarto/bib/",
      "^latexmkrc$",
      "^man/",
      "^src/",
      "^vignettes/",
      "^\\.setup/latex/pdf/",
      "^\\.setup/latex/figures/",
      "^\\.setup/data-analysis/.*\\.txt$",
      "^data/.*\\.rda$",
      "^NAMESPACE$",
      "^AGENTS\\.md$",
      "^CLAUDE\\.md$",
      "^\\.github/copilot-instructions\\.md$",
      "^\\.Rbuildignore$",
      "^project\\.Rproj$",
      "^README\\.md$",
      "^CITATION\\.cff$",
      "^LICENSE",
      "^R/RcppExports\\.R$",
      "bib\\.bib$",
      "^\\.Renviron$",
      "^\\.Rprofile$",
      "secrets",
      "TEMPDIR"
    ),
    collapse = "|"
  )
  files <- function(root) {
    out <- list.files(
      path = root,
      all.files = TRUE,
      recursive = TRUE,
      no.. = TRUE
    )
    out[!grepl(pattern = skip, x = out)]
  }
  candidates <- sort(union(files(path), files(private)))
  # tier 2 template files are written by make (Template()), not uploaded
  type <- .TemplateType(path = path)
  if (!is.null(type)) {
    files <- .TemplateFiles(type = type)
    candidates <- setdiff(
      candidates,
      files$path[files$tier == "2"]
    )
  }
  status <- vapply(
    X = candidates,
    FUN = function(file) {
      .VerifyCompare(
        path = path,
        private = private,
        file = file
      )
    },
    FUN.VALUE = character(1)
  )
  status[status != "match"]
}
